/* Exifo service worker. Generated by scripts/build-sw.mjs; do not edit out/sw.js directly. */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const APP_CACHE = `exifo-app-${VERSION}`;
const RUNTIME = "exifo-runtime-v1";
const SHARE_CACHE = "exifo-share-v1";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(APP_CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("exifo-app-") && k !== APP_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

/** Files shared from the OS share sheet are parked in a cache, then the app opens them. */
async function handleShare(request) {
  try {
    const data = await request.formData();
    const files = data.getAll("images").filter((f) => typeof f !== "string");
    const cache = await caches.open(SHARE_CACHE);
    await Promise.all(
      files.map((file, i) =>
        cache.put(
          `/__shared/${Date.now()}-${i}`,
          new Response(file, {
            headers: {
              "content-type": file.type || "application/octet-stream",
              "x-file-name": encodeURIComponent(file.name || `shared-${i + 1}`),
              "x-last-modified": String(file.lastModified || Date.now()),
            },
          }),
        ),
      ),
    );
  } catch {
    // fall through to the app; nothing to open
  }
  return Response.redirect("/clean/?shared=1", 303);
}

async function navigation(request) {
  try {
    const res = await fetch(request);
    if (res.ok) {
      const cache = await caches.open(APP_CACHE);
      cache.put(request, res.clone());
    }
    return res;
  } catch {
    const url = new URL(request.url);
    const path = url.pathname.endsWith("/") ? url.pathname : `${url.pathname}/`;
    return (
      (await caches.match(path, { ignoreSearch: true })) ||
      (await caches.match("/", { ignoreSearch: true })) ||
      new Response("You are offline.", { status: 503, headers: { "content-type": "text/plain" } })
    );
  }
}

async function cacheFirst(request, cacheName, ignoreSearch) {
  const hit = await caches.match(request, { ignoreSearch });
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok && res.type === "basic") {
    const cache = await caches.open(cacheName);
    cache.put(request, res.clone());
  }
  return res;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method === "POST" && url.origin === self.location.origin && url.pathname === "/share-target/") {
    event.respondWith(handleShare(request));
    return;
  }
  if (request.method !== "GET" || url.origin !== self.location.origin) return;
  if (request.mode === "navigate") {
    event.respondWith(navigation(request));
    return;
  }
  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, url.pathname.endsWith(".wasm") ? RUNTIME : APP_CACHE, false));
    return;
  }
  if (url.pathname.endsWith(".txt")) {
    // React Server Component payloads used for client-side navigation.
    event.respondWith(fetch(request).catch(async () => (await caches.match(request, { ignoreSearch: true })) || Response.error()));
    return;
  }
  event.respondWith(cacheFirst(request, url.pathname.startsWith("/wasm/") ? RUNTIME : APP_CACHE, false));
});
